function PersonClaims({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: all = [] } = useClaims(sheet);
  const claims = all.filter((c) => c.personId === person.id);
  const today = useSheetToday(sheet);
  // Their OPEN and PENDING claims dated within a hold, or all of them once today reaches their
  // retirement date, count toward neither claimed nor the due-total, unless a statement binds them.
  const liveClaims = live(claims, (_, date) => heldOn(person, date, today));
  const { data: everyone = [] } = usePeople(sheet);
  const others = everyone.filter((p) => p.id !== person.id);
  const { data: rates = [] } = useRates(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const pct = rateOn(rates, gradeOn(person, today), today);
  const floor = useFloor(sheet);
  const lateBy = useLate(sheet);
  const cap = useCap(sheet);
  // The sum of their figures; their due-total is at most the cap, the rest their excess.
  const dueSum = personDueCents(liveClaims, floor, pct, (d) => rateOn(rates, gradeOn(person, d), d), lateBy);
  // The due-total before the cap, split (an n/a part shows 0.00): their SETTLED claims' figures, and their OPEN and PENDING ones'.
  const settledSum = personDueCents(liveClaims.filter((c) => c.status === 'SETTLED'), floor, pct, (d) => rateOn(rates, gradeOn(person, d), d), lateBy);
  const openSum = personDueCents(liveClaims.filter(isOpen), floor, pct, (d) => rateOn(rates, gradeOn(person, d), d), lateBy);
  const late = overdueFigures(liveClaims, lateBy, floor, (d) => rateOn(rates, gradeOn(person, d), d));
  // The claim whose editor this user has open: the one their lock holds, so it stays open across a re-load.
  const editingClaim = claims.find((c) => c.lockedBy === user) ?? null;
  batch: number | null;
};

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** Every claim on the sheet, newest first, re-read whenever the sheet is loaded. */
export function useClaims(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(claimsKey(sheet), asOf),
    queryFn: () => getJson<Claim[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The number of the sheet's last bulk settle batch; null when there has been none. */
export function lastBatch(claims: Claim[]): number | null {
  return claims.reduce<number | null>((last, c) => (c.batch != null && (last == null || c.batch > last) ? c.batch : last), null);
}

